H=Path(__file__).resolve().parent
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
def write(n,o):(H/'evaluation'/n).write_text(json.dumps(o,indent=2,ensure_ascii=False)+'\n',encoding='utf8')
CLASSES=('CHEMICALLY_EQUIVALENT','CHEMICALLY_DIFFERENT','CHEMICALLY_UNRESOLVED')
def metrics(records):
 labelled=[r for r in records if r['accuracy_population_eligible'] and r['expected_correspondence'] in CLASSES]
 matrix={e:{a:0 for a in CLASSES} for e in CLASSES}
 for r in labelled:matrix[r['expected_correspondence']][r['actual_correspondence']]+=1
 stats={}
 for category in CLASSES:
  tp=matrix[category][category];predicted=sum(matrix[e][category] for e in CLASSES);actual=sum(matrix[category].values());precision=tp/predicted if predicted else None;recall=tp/actual if actual else None
  stats[category]=dict(true_positive=tp,predicted_count=predicted,reference_count=actual,precision=precision,recall=recall,F1=2*precision*recall/(precision+recall) if precision is not None and recall is not None and precision+recall else None)
 n=len(labelled);correct=sum(matrix[c][c] for c in CLASSES)
 return dict(cases=len(records),labelled_population=n,reference_coverage=n/len(records) if records else None,confusion_matrix=matrix,per_class=stats,exact_equivalence_precision=stats[CLASSES[0]]['precision'],exact_equivalence_recall=stats[CLASSES[0]]['recall'],exact_equivalence_F1=stats[CLASSES[0]]['F1'],false_equivalence_count=sum(matrix[e][CLASSES[0]] for e in CLASSES[1:]),false_difference_count=matrix[CLASSES[0]][CLASSES[1]]+matrix[CLASSES[2]][CLASSES[1]],unnecessary_abstentions=matrix[CLASSES[0]][CLASSES[2]]+matrix[CLASSES[1]][CLASSES[2]],observed_abstention_count=sum(matrix[e][CLASSES[2]] for e in CLASSES),abstention_rate=sum(matrix[e][CLASSES[2]] for e in CLASSES)/n if n else None,documentary_agreement_count=correct,documentary_agreement_rate=correct/n if n else None,scope='Selected represented graphs/compositions, measured against documentary labels; not independently corroborated canonical identities or population precision',expert_certified=False)
def main():
 cases={c['case_id']:c for c in read(H/'reference_corpus/reference_cases.json')['cases']}
 parts={p:read(H/f'evaluation/{p}_results.json')['cases'] for p in ('development_reference','frozen_evaluation')};allrows=parts['development_reference']+parts['frozen_evaluation']
 rates=dict(partitions={p:metrics(rows) for p,rows in parts.items()},documentary_real_reference_population=metrics(allrows),expert_reviewed_population=dict(cases=0,precision=None,recall=None,F1=None,reason='NO_QUALIFIED_EXPERT_REVIEW_PERFORMED'),independently_corroborated_accuracy=dict(cases=0,precision=None,recall=None,F1=None,reason='UPSTREAM_INDEPENDENCE_UNESTABLISHED'),excluded_cases=[dict(case_id=r['case_id'],reason=cases[r['case_id']]['scientific_justification'],actual=r['actual_correspondence']) for r in allrows if not r['accuracy_population_eligible']],reference_labels_from_resolver=False,blinding='NOT_BLINDED')
 write('precision_recall_f1.json',rates)
 write('chemical_correspondence_results.json',dict(metrics=rates['documentary_real_reference_population'],cases=allrows))
 identity_counts=collections.Counter(r['actual_source_correspondence'] for r in allrows)
 write('identity_correspondence_results.json',dict(outcomes=dict(identity_counts),chemical_equivalence_without_source_specificity=[r['case_id'] for r in allrows if r['actual_correspondence']==CLASSES[0] and r['result']['source_specificity']['state']!='SUFFICIENTLY_SPECIFIED_SOURCE_IDENTITY'],reference_record_inconsistency_withheld=[r['case_id'] for r in allrows if any(o['reason']=='CANDIDATE_IDENTIFIER_STRUCTURE_INCONSISTENCY' for o in r['result']['unresolved_obligations'])],case_results=[dict(case_id=r['case_id'],status=r['actual_source_correspondence'],expected_source_status=r['expected_source_correspondence'],specificity=r['result']['source_specificity']['state'],independently_corroborated=r['result']['source_identity_correspondence']['independently_corroborated_exact_identity']) for r in allrows]))
 registry=read(H/'evaluation/registry_candidate_results.json');peer=read(H/'evaluation/pubchem_chebi_pair_results.json')
 write('evidence_independence_results.json',dict(corpus=dict(counts=dict(collections.Counter(r['actual_independence'] for r in allrows)),incorrect_independence_claims=sum(r['actual_independence']=='INDEPENDENTLY_ESTABLISHED' and r['expected_independence']!='INDEPENDENTLY_ESTABLISHED' for r in allrows),reviewed_positive_independence_examples=0),saved_pairs=peer['independence_counts'],registry_candidates=dict(collections.Counter(a['evidence_independence']['status'] for r in registry['queries'] for a in r['assessments'])),note='Unknown is an evidence assessment, not a truth claim that sources are dependent. Known shared record roots in registry matches are explicit dependence. Documentary grounding and expert review are separate axes.'))
 write('admission_assessment_results.json',dict(corpus_cases=len(allrows),eligible=sum(r['result']['admission_eligibility']['eligible'] for r in allrows),withheld=sum(not r['result']['admission_eligibility']['eligible'] for r in allrows),sufficiently_specified_source_identities=sum(r['result']['source_specificity']['state']=='SUFFICIENTLY_SPECIFIED_SOURCE_IDENTITY' for r in allrows),supported_source_identity_without_qualifying_corroboration=sum(r['actual_source_correspondence']=='SOURCE_IDENTITY_CORRESPONDENCE_SUPPORTED' and r['result']['corroboration_qualification']['independent_corroboration']=='NOT_ESTABLISHED' for r in allrows),all_diagnostic_requirements_satisfied=0,unsafe_admission_recommendations=sum(r['result']['admission_eligibility']['eligible'] for r in allrows)+peer['unsafe_admission_recommendations']+sum(a['admission_eligibility']['eligible'] for r in registry['queries'] for a in r['assessments']),existing_policy_reason_counts=dict(collections.Counter(code for r in allrows for code in r['result']['admission_eligibility']['existing_policy_result']['reason_codes'])),limits='Existing admission policy exercised with official reference-InChI validation absent and no qualifying external provider evidence supplied. No positive admission route was validated here. Typed-input exemptions in existing policy remain unchanged.'))
 taxonomy=[];reference_findings=[]
 for r in allrows:
  c=cases[r['case_id']];causes=['PROVENANCE_OR_INDEPENDENCE_UNCERTAINTY','EXTERNAL_CORROBORATION_LIMITATION'];s=r['result']['source_specificity'];obligations=r['result']['unresolved_obligations']
  if s['state']!='SUFFICIENTLY_SPECIFIED_SOURCE_IDENTITY':causes.append('INSUFFICIENT_SOURCE_SPECIFICITY')
